<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Cache,Event,Notification,Gate,DB};
use Illuminate\Support\Str;
use App\Models\{User,Field,Location,Booking,PaymentEvent};
use App\Services\{BookingEngine,Slots};
use Carbon\CarbonImmutable;
use Symfony\Component\HttpKernel\Exception\HttpException;
class BookingTest extends TestCase {
 use RefreshDatabase;
 private User $citizen;private Field $field;private BookingEngine $engine;
 protected function setUp():void {parent::setUp();Event::fake([\App\Events\SlotChanged::class]);Notification::fake();$this->travelTo(CarbonImmutable::parse('2030-10-27T07:00:00+03:00'));$l=Location::create(['region'=>'Addis Ababa','subcity'=>'Bole','woreda'=>'03']);$this->citizen=User::create(['national_id'=>'1000000001','first_name'=>'Test','last_name'=>'Citizen','role'=>'USER']);$this->field=Field::create(['location_id'=>$l->id,'name'=>'Test field','type'=>'FOOTBALL','price_per_hour'=>'800.00','status'=>'ACTIVE','operating_hours'=>['start'=>'08:00','end'=>'22:00']]);$this->engine=app(BookingEngine::class);}
 protected function tearDown():void {foreach(Booking::all() as $b){if($b->lock_owner)Cache::store('redis')->restoreLock('slot:'.$b->field_id.':'.$b->start_time->getTimestamp(),$b->lock_owner)->release();}parent::tearDown();}
 private function hold(string $time='08:00',?string $key=null):Booking{return $this->engine->hold($this->citizen,$this->field,'2030-10-28',$time,'Test United',$key??(string)Str::uuid());}
 private function paid():Booking{$b=$this->hold();return $this->engine->settle($b->id,'TX-'.Str::uuid(),$b->telebirr_amount,'ETB',true);}
 public function test_slots_include_fifteen_minute_changeover():void {$s=app(Slots::class)->starts($this->field,'2030-10-28');$this->assertSame('09:15',$s[1]->timezone('Africa/Addis_Ababa')->format('H:i'));$this->assertSame(75,(int)$s[0]->diffInMinutes($s[1]));}
 public function test_same_request_returns_same_hold():void {$key=(string)Str::uuid();$a=$this->hold(key:$key);$b=$this->hold(key:$key);$this->assertSame($a->id,$b->id);}
 public function test_two_users_cannot_hold_the_same_slot():void {$this->hold();$other=User::create(['national_id'=>'1000000002','first_name'=>'Other','last_name'=>'Citizen','role'=>'USER']);$this->expectException(HttpException::class);$this->engine->hold($other,$this->field,'2030-10-28','08:00','Other team',(string)Str::uuid());}
 public function test_credit_is_reserved_and_restored_on_expiry():void {$this->citizen->store_credit='500.00';$this->citizen->save();$b=$this->hold();$this->assertSame('300.00',$b->telebirr_amount);$this->assertSame('0.00',$this->citizen->fresh()->store_credit);$this->travel(301)->seconds();$this->engine->expire();$this->assertSame('EXPIRED',$b->fresh()->status);$this->assertSame('500.00',$this->citizen->fresh()->store_credit);}
 public function test_duplicate_callback_has_one_payment_record():void {$b=$this->hold();$this->engine->settle($b->id,'same-ref','800.00','ETB',true);$this->engine->settle($b->id,'same-ref','800.00','ETB',true);$this->assertSame(1,PaymentEvent::where('provider_ref','same-ref')->count());$this->assertSame('PAID',$b->fresh()->status);}
 public function test_amount_mismatch_never_generates_a_pass():void {$b=$this->hold();try{$this->engine->settle($b->id,'bad','1.00','ETB',true);$this->fail('Amount was accepted');}catch(HttpException $e){$this->assertSame(422,$e->getStatusCode());}$this->assertNull($b->fresh()->qr_hash);}
 public function test_late_payment_requires_review_and_does_not_book():void {$b=$this->hold();$this->travel(301)->seconds();$this->engine->settle($b->id,'late','800.00','ETB',true);$this->assertSame('EXPIRED',$b->fresh()->status);$this->assertSame('REVIEW_REQUIRED',PaymentEvent::where('provider_ref','late')->value('status'));$this->assertNull($b->fresh()->qr_hash);}
 public function test_cancellation_is_store_credit_and_idempotent():void {$b=$this->paid();$this->engine->cancel($this->citizen,$b);$this->engine->cancel($this->citizen,$b);$this->assertSame('800.00',$this->citizen->fresh()->store_credit);$this->assertSame('CANCELLED',$b->fresh()->status);$this->assertNull($b->fresh()->qr_hash);}
 public function test_cancellation_rejects_exact_two_hour_boundary():void {$b=$this->paid();$this->travelTo($b->start_time->subHours(2));$this->expectException(HttpException::class);$this->engine->cancel($this->citizen,$b);}
 public function test_gate_pass_is_current_assigned_and_single_use():void {$op=User::create(['national_id'=>'STAFF-1','first_name'=>'Gate','last_name'=>'Keeper','role'=>'OPERATOR','location_id'=>$this->field->location_id]);$this->field->operator_user_id=$op->id;$this->field->save();$b=$this->paid();$this->travelTo($b->start_time);$token=$this->engine->token($b);$this->assertSame('CHECKED_IN',$this->engine->checkIn($op,$this->field->id,$token)->status);$this->expectException(HttpException::class);$this->engine->checkIn($op,$this->field->id,$token);}
 public function test_woreda_supervisor_cannot_edit_other_woredas():void {$u=User::create(['national_id'=>'STAFF-2','first_name'=>'Supervisor','last_name'=>'','role'=>'WOREDA_ADMIN','location_id'=>$this->field->location_id]);$other=Location::create(['region'=>'Addis Ababa','subcity'=>'Bole','woreda'=>'05']);$f=Field::create(['location_id'=>$other->id,'name'=>'Other field','price_per_hour'=>'800.00','operating_hours'=>['start'=>'08:00','end'=>'22:00']]);$this->assertTrue(Gate::forUser($u)->allows('update',$this->field));$this->assertFalse(Gate::forUser($u)->allows('update',$f));$this->assertSame(1,Field::visibleTo($u)->count());}
 public function test_postgres_constraint_rejects_an_overlap_inside_the_buffer():void {$b=$this->hold();$this->expectException(\Illuminate\Database\QueryException::class);DB::transaction(function()use($b){$copy=$b->replicate();$copy->id=(string)Str::uuid();$copy->idempotency_key=(string)Str::uuid();$copy->start_time=$b->start_time->addMinutes(60);$copy->end_time=$copy->start_time->addMinutes(60);$copy->reserved_until=$copy->end_time->addMinutes(15);$copy->save();});}
 public function test_mock_identity_cannot_set_staff_role():void {$this->post('/login',['fan'=>'9999999999','role'=>'SUPER_ADMIN'])->assertRedirect('/');$this->assertSame('USER',User::where('national_id','9999999999')->value('role'));}
 public function test_unconfigured_webhook_cannot_mark_any_payment_paid():void {$b=$this->hold();$this->postJson('/api/payments/telebirr/callback',['booking_id'=>$b->id,'status'=>'SUCCESS'])->assertStatus(503);$this->assertSame('PENDING_PAYMENT',$b->fresh()->status);}
}
